use compiled_successor_v19::invocation_load;
pub(super) enum InvocationGuard {
    Current,
    #[cfg(test)]
    Disabled,
}
impl InvocationGuard {
    fn read(&self, path: &Path, length: usize, sha: &str) -> Result<String, &'static str> {
        held_4a6eb(path, length, sha)
    }
    fn disabled(&self) -> bool {
        #[cfg(test)]
        if matches!(self, Self::Disabled) {
            return true;
        }
        false
    }
    pub(super) fn check(&self, stage: bool) {
        if self.disabled() {
            return;
        }
        #[cfg(test)]
        super::historical_before_data::invocation_probe::note(false);
        let root = Path::new(env!("CARGO_MANIFEST_DIR"));
        for &(path, length, sha) in INVOCATION_PACKET_READS {
            self.read(&root.join(path), length, sha).unwrap();
        }
        let (_, page) = invocation_load(&|p, n, h| self.read(p, n, h)).unwrap();
        compiled_successor_v19::authenticate20_using(&page, &|p, n, h| self.read(p, n, h)).unwrap();
        compiled_successor_v19::authenticate_using(&page, &|p, n, h| self.read(p, n, h)).unwrap();
        for (path, compiled) in invocation_controllers() {
            assert_eq!(
                self.read(
                    &root.join(path),
                    compiled.len(),
                    &digest(compiled.as_bytes())
                )
                .unwrap(),
                compiled,
                "live invocation controller"
            );
        }
        if stage {
            self.stage();
        }
    }
    pub(super) fn stage(&self) {
        if self.disabled() {
            return;
        }
        #[cfg(test)]
        super::historical_before_data::invocation_probe::note(true);
        for (path, compiled) in invocation_stages() {
            assert_eq!(
                self.read(
                    &Path::new(env!("CARGO_MANIFEST_DIR")).join(path),
                    compiled.len(),
                    &digest(compiled.as_bytes())
                )
                .unwrap(),
                compiled,
                "live invocation stage"
            );
        }
    }
    pub(super) fn after_body(&self) {
        #[cfg(test)]
        if !self.disabled() {
            super::historical_before_data::invocation_probe::after_body();
        }
    }
}
